mapper.select:
SELECT * FROM sys_business_task_definition WHERE tenant_id=#{tenantId} AND source_type=#{sourceType} AND del_flag=0
  AND id > #{afterId}
ORDER BY id LIMIT #{limit}

SELECT * FROM sys_business_task WHERE tenant_id=#{tenantId} AND definition_id=#{definitionId}
  AND source_key=#{sourceKey} AND occurrence_key=#{occurrenceKey} AND assignee_id=#{assigneeId}
  AND del_flag=0 FOR UPDATE

SELECT * FROM sys_business_task WHERE tenant_id=#{tenantId} AND assignee_id=#{assigneeId}
  AND state!='DRAFT' AND del_flag=0
  AND state=#{state}
  AND id > #{afterId}
ORDER BY id LIMIT #{limit}
